func searchNameContainsTerm(lowerName, term string) bool {
	if len(term) < 3 {
		return false
	}
	if strings.Contains(lowerName, term) {
		return true
	}
	if strings.HasSuffix(term, "es") && len(term) > 4 && strings.Contains(lowerName, term[:len(term)-2]) {
